# Alternative implementation using built-in int and bin functions
def string_xor_alt(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor_alt('010', '110')
    '100'
    """
    if len(a) != len(b):
        raise ValueError("Both strings must be of the same length")

    return bin(int(a, 2) ^ int(b, 2))[2:].zfill(len(a))

# Example usage
if __name__ == "__main__":
    print(string_xor('010', '110'))  # Outputs: 100
    print(string_xor_alt('010', '110'))  # Outputs: 100

